	public void activateObjectsMode()
    {
		ctx = XmlSchemaContext.deserialize(CTX_XML);

		using (Transaction tx = tb.startTransaction())
{
			tb.trace.getObjectManager().createRootObject(ctx.getSchema(new SchemaName("Session")));
		}
	}

	protected TraceMemoryRegion addRegion(string name, long loaded, AddressRange range) {
		bool isData = name.endsWith(".data");
		TraceObjectManager om = tb.trace.getObjectManager();
		KeyPath memPath = KeyPath.parse("Memory");
		Lifespan span = Lifespan.nowOn(loaded);
		TraceMemoryRegion region = Objects.requireNonNull(om.createObject(memPath.index(name))
				.insert(span, ConflictResolution.TRUNCATE)
				.getDestination(null)
				.queryInterface(typeof(TraceMemoryRegion)));
		TraceObject obj = region.getObject();
		obj.setAttribute(span, TraceMemoryRegion.KEY_DISPLAY, name);
		obj.setAttribute(span, TraceMemoryRegion.KEY_RANGE, range);
		obj.setAttribute(span, TraceMemoryRegion.KEY_READABLE, true);
		obj.setAttribute(span, TraceMemoryRegion.KEY_WRITABLE, isData);
		obj.setAttribute(span, TraceMemoryRegion.KEY_EXECUTABLE, !isData);
		return region;
	}

	protected void addRegions()
    {
		using (Transaction tx = tb.startTransaction())
{
			regionExeText = addRegion("/bin/echo .text", 0, tb.range(0x55550000, 0x555500ff));
			regionExeData = addRegion("/bin/echo .data", 0, tb.range(0x55750000, 0x5575007f));
			regionLibText = addRegion("/lib/libc.so .text", 0, tb.range(0x7f000000, 0x7f0003ff));
			regionLibData = addRegion("/lib/libc.so .data", 0, tb.range(0x7f100000, 0x7f10003f));
		}
	}

	protected void addBlocks()
    {
		using (Transaction tx = program.openTransaction("Add block"))
{
			Memory mem = program.getMemory();
			blockExeText = mem.createInitializedBlock(".text", tb.addr(0x00400000), 0x100, (byte) 0,
				monitor, false);
			blockExeData = mem.createInitializedBlock(".data", tb.addr(0x00600000), 0x80, (byte) 0,
				monitor, false);
		}
	}

	protected void assertTableSize(int size) {
		assertEquals(size, provider.panel.getAllItems().size());
	}

	protected void assertRow(int position, object @object, string name, Address start, Address end,
			long length, string flags) {
		ValueRow row = provider.panel.getAllItems().get(position);
		var tableModel = QueryPanelTestHelper.getTableModel(provider.panel);
		GhidraTable table = QueryPanelTestHelper.getTable(provider.panel);
		DynamicTableColumn<ValueRow,object, Trace> nameCol =
			QueryPanelTestHelper.getColumnByNameAndType(tableModel, table, "Name", typeof(ValueRow))
					.column();
		DynamicTableColumn<ValueRow,object, Trace> startCol = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "Start", typeof(ValueProperty))
				.column();
		DynamicTableColumn<ValueRow,object, Trace> endCol = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "End", typeof(ValueProperty))
				.column();
		DynamicTableColumn<ValueRow,object, Trace> lengthCol = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "Length", typeof(ValueProperty))
				.column();
		DynamicTableColumn<ValueRow,object, Trace> readCol = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "Read", typeof(ValueProperty))
				.column();
		DynamicTableColumn<ValueRow,object, Trace> writeCol = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "Write", typeof(ValueProperty))
				.column();
		DynamicTableColumn<ValueRow,object, Trace> executeCol = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "Execute", typeof(ValueProperty))
				.column();

		assertSame(@object, row.getValue().getValue());
		assertEquals(name, rowColDisplay(row, nameCol));
		assertEquals(start, rowColVal(row, startCol));
		assertEquals(end, rowColVal(row, endCol));
		assertEquals(length, rowColVal(row, lengthCol));
		assertEquals(flags.contains("r"), rowColVal(row, readCol));
		assertEquals(flags.contains("w"), rowColVal(row, writeCol));
		assertEquals(flags.contains("x"), rowColVal(row, executeCol));
	}

